CREATE OR REPLACE TRIGGER GL.account_gl_update
after update on pm_accounts
for each row
begin

update pm_general_ledger
set actname=:new.actname
where actcode=:old.actcode
and   parent=:old.parent;

update pm_journaldl
set actname=:new.actname,
parent = :new.parent
where actcode=:old.actcode;



end;
/


CREATE OR REPLACE TRIGGER GL.new_customer_update
after update on pm_customer
for each row
Declare
       v_lvl        number(3);
begin


 update pm_accounts
 set actname =:new.custname
 where actcode=:old.custcode
 and   parent=:old.parent;


end;
/


CREATE OR REPLACE TRIGGER GL.new_customer
after insert on pm_customer
for each row
Declare
       v_lvl        number(3);
begin


 insert into pm_accounts(actcode,actname,parent,prefix,lvl)
 values(:new.custcode,:new.custname,:new.parent,:new.prefix,:new.lvl);
end;
/


CREATE OR REPLACE TRIGGER GL.journal_item_delete
after delete on pm_journal_jv
for each row
declare

    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);
    v_actname            varchar2(200);

begin

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    select actname
    into v_actname
    from pm_accounts
    where actcode = :old.actcode;

    select getSuperParent(v_actname)
    into v_superparent
    from dual;

    if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

        update pm_journaldl
        set balance = balance - nvl(:old.dramount,0) + nvl(:old.cramount,0)
        where actcode = :old.actcode
        and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no);

        if v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability') then

            dbms_output.put_line(v_opening_date||' to '||v_closing_date);
            pfCalc(v_opening_date, v_closing_date);

        end if;

    elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

        update pm_journaldl
        set balance = balance - nvl(:old.dramount,0) + nvl(:old.cramount,0)
        where actcode = :old.actcode
        and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no)
        and vdate <= v_closing_date;

    end if;

    delete from pm_journaldl
    where ref_no = :old.ref_no;

end;
/


CREATE OR REPLACE TRIGGER GL.journal_voucher
after insert on pm_journal_jv
for each row
declare

    v_parent            pm_accounts.parent%type;
    v_lvl                pm_accounts.lvl%type;
    v_actname            pm_accounts.actname%type;
    v_vdate                date;
    v_balance            pm_journaldl.balance%type:=0;
    v_count                number(32);
    v_balance_count        number(32);
    v_max_journalno        number(32);
    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);


begin
    -- for new head of accounts

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    select parent, lvl, actname
    into v_parent, v_lvl, v_actname
    from pm_accounts
    where actcode = :new.actcode;

    select vdate
    into v_vdate
    from pm_journal_voucher
    where voucherno = :new.voucherno;

    select getSuperParent(v_actname)
    into v_superparent
    from dual;

    if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

        select count(*)
        into v_balance_count
        from pm_journaldl
        where actcode = :new.actcode
        and vdate <= v_vdate;

        select nvl(max(nvl(journalno,0)),0)
        into v_max_journalno
        from pm_journaldl
        where vdate <= v_vdate;

        if v_balance_count > 0 then

            select balance
            into v_balance
            from pm_journaldl
            where actcode = :new.actcode
            and journalno =
                (select max(journalno)
                from pm_journaldl
                where actcode = :new.actcode
                and vdate <= v_vdate);
        end if;

        update pm_journaldl set balance = balance + nvl(:new.dramount,0) - nvl(:new.cramount,0)
        where journalno > v_max_journalno
        and actcode = :new.actcode;

        update pm_journaldl set journalno = journalno + 1
        where journalno > v_max_journalno;

        insert into pm_journaldl(voucherno, vdate, actcode, actname,
        dramount, cramount, balance, journalno, ref_no)
        values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
        nvl(:new.dramount,0), nvl(:new.cramount,0),
        v_balance + (nvl(:new.dramount,0)-nvl(:new.cramount,0)),
        v_max_journalno+1, :new.ref_no);

        if v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability') then

            dbms_output.put_line(v_opening_date||' to '||v_closing_date);
            pfCalc(v_opening_date, v_closing_date);

        end if;

    elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

        select count(*)
        into v_balance_count
        from pm_journaldl
        where actcode = :new.actcode
        and vdate <= v_vdate;

        select nvl(max(nvl(journalno,0)),0)
        into v_max_journalno
        from pm_journaldl
        where vdate <= v_vdate;

        if v_balance_count > 0 then

            select balance
            into v_balance
            from pm_journaldl
            where actcode = :new.actcode
            and journalno =
                (select max(journalno)
                from pm_journaldl
                where actcode = :new.actcode
                and vdate <= v_vdate);
        end if;

        update pm_journaldl set balance = balance + nvl(:new.dramount,0) - nvl(:new.cramount,0)
        where journalno > v_max_journalno
        and actcode = :new.actcode
        and vdate <= v_closing_date;

        update pm_journaldl set journalno = journalno + 1
        where journalno > v_max_journalno;

        insert into pm_journaldl(voucherno, vdate, actcode, actname,
        dramount, cramount, balance, journalno, ref_no)
        values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
        nvl(:new.dramount,0), nvl(:new.cramount,0),
        v_balance + (nvl(:new.dramount,0)-nvl(:new.cramount,0)),
        v_max_journalno+1, :new.ref_no);


    end if;


end;
/


CREATE OR REPLACE TRIGGER GL.journal_voucher_update
after update on pm_journal_jv
for each row
declare

    v_parent            pm_accounts.parent%type;
    v_lvl                pm_accounts.lvl%type;
    v_actname            pm_accounts.actname%type;
    v_vdate                date;
    v_journalno            number(32);
    v_c                    number(32);
    v_balance            number(32,2);
    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);
    v_oldactname        varchar2(200);
    v_oldsuperparent    varchar2(200);

begin

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    select parent, lvl, actname
    into v_parent, v_lvl, v_actname
    from pm_accounts
    where actcode = :new.actcode;

    select vdate
    into v_vdate
    from pm_journal_voucher
    where voucherno = :new.voucherno;

    select getSuperParent(v_actname)
    into v_superparent
    from dual;

    select actname
    into v_oldactname
    from pm_accounts
    where actcode = :old.actcode;

    select getSuperParent(v_oldactname)
    into v_oldsuperparent
    from dual;

    if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

        if :new.actcode <> :old.actcode then

            select journalno
            into v_journalno
            from pm_journaldl
            where ref_no = :new.ref_no;

            delete from pm_journaldl where ref_no = :new.ref_no;

            if v_oldsuperparent = 'Revenue' or v_oldsuperparent ='Expense' then

                update pm_journaldl
                set balance = balance - nvl(:old.dramount,0) + nvl(:old.cramount,0)
                where actcode = :old.actcode
                and journalno > v_journalno
                and vdate <= v_closing_date;

            else

                update pm_journaldl
                set balance = balance - nvl(:old.dramount,0) + nvl(:old.cramount,0)
                where actcode = :old.actcode
                and journalno > v_journalno;

            end if;

            select nvl(max(nvl(journalno,0)),0)
            into v_journalno
            from pm_journaldl
            where vdate <= v_vdate;

            select count(*)
            into v_c
            from pm_journaldl
            where actcode = :new.actcode
            and vdate <= v_vdate;

            if v_c > 0 then

                select balance
                into v_balance
                from pm_journaldl
                where actcode = :new.actcode
                and journalno = (select max(journalno) from pm_journaldl where actcode = :new.actcode and
                                    vdate <= v_vdate);

            else

                v_balance := 0;

            end if;

            update pm_journaldl
            set balance = balance + nvl(:new.dramount,0) - nvl(:new.cramount,0)
            where actcode = :new.actcode
            and journalno > v_journalno;

            update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
            nvl(:new.dramount,0), nvl(:new.cramount,0),
            v_balance + (nvl(:new.dramount,0)-nvl(:new.cramount,0)),
            v_journalno+1, :new.ref_no);


        elsif :new.actcode = :old.actcode then

            select journalno, balance
            into v_journalno, v_balance
            from pm_journaldl
            where ref_no = :new.ref_no;

            update pm_journaldl
            set dramount = nvl(:new.dramount,0), cramount = nvl(:new.cramount,0),
            balance = balance + (nvl(:new.dramount,0) - nvl(:old.dramount,0)) - (nvl(:new.cramount,0) - nvl(:old.cramount,0))
            where ref_no = :new.ref_no;

            update pm_journaldl
            set balance = balance + (nvl(:new.dramount,0) - nvl(:old.dramount,0)) - (nvl(:new.cramount,0) - nvl(:old.cramount,0))
            where actcode = :new.actcode
            and journalno > v_journalno;

        end if;

        if v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability') then

            dbms_output.put_line(v_opening_date||' to '||v_closing_date);
            pfCalc(v_opening_date, v_closing_date);

        end if;


    elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

        if :new.actcode <> :old.actcode then

            select journalno
            into v_journalno
            from pm_journaldl
            where ref_no = :new.ref_no;

            delete from pm_journaldl where ref_no = :new.ref_no;

            update pm_journaldl
            set balance = balance - nvl(:old.dramount,0) + nvl(:old.cramount,0)
            where actcode = :old.actcode
            and journalno > v_journalno
            and vdate <= v_closing_date;

            select nvl(max(nvl(journalno,0)),0)
            into v_journalno
            from pm_journaldl
            where vdate <= v_vdate;

            select count(*)
            into v_c
            from pm_journaldl
            where actcode = :new.actcode
            and vdate <= v_vdate;

            if v_c > 0 then

                select balance
                into v_balance
                from pm_journaldl
                where actcode = :new.actcode
                and journalno = (select max(journalno) from pm_journaldl where actcode = :new.actcode and
                                    vdate <= v_vdate);

            else

                v_balance := 0;

            end if;

            update pm_journaldl
            set balance = balance + nvl(:new.dramount,0) - nvl(:new.cramount,0)
            where actcode = :new.actcode
            and journalno > v_journalno
            and vdate <= v_closing_date;

            update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
            nvl(:new.dramount,0), nvl(:new.cramount,0),
            v_balance + (nvl(:new.dramount,0)-nvl(:new.cramount,0)),
            v_journalno+1, :new.ref_no);


        elsif :new.actcode = :old.actcode then

            select journalno, balance
            into v_journalno, v_balance
            from pm_journaldl
            where ref_no = :new.ref_no;

            update pm_journaldl
            set dramount = nvl(:new.dramount,0), cramount = nvl(:new.cramount,0),
            balance = balance + (nvl(:new.dramount,0) - nvl(:old.dramount,0)) - (nvl(:new.cramount,0) - nvl(:old.cramount,0))
            where ref_no = :new.ref_no;

            update pm_journaldl
            set balance = balance + (nvl(:new.dramount,0) - nvl(:old.dramount,0)) - (nvl(:new.cramount,0) - nvl(:old.cramount,0))
            where actcode = :new.actcode
            and journalno > v_journalno
            and vdate <= v_closing_date;

        end if;

    end if;

end;
/


CREATE OR REPLACE TRIGGER GL.journal_master_update
after update of vdate on pm_journal_voucher
for each row
declare

    CURSOR jv is select actcode,nvl(dramount,0),nvl(cramount,0), ref_no
            from pm_journal_jv
            where voucherno = :new.voucherno;

    jv_actcode        pm_accounts.actcode%type;
    jv_dramount        pm_journal_jv.dramount%type;
    jv_cramount        pm_journal_jv.cramount%type;
    jv_ref_no        pm_journal_jv.ref_no%type;
    v_parent        pm_accounts.parent%type;
    v_lvl            pm_accounts.lvl%type;
    v_actname        pm_accounts.actname%type;
    v_c                number(32);
    v_journalno        number(32);
    v_balance        number(32,2);
    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);


begin

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    if :new.vdate <> :old.vdate then

        open jv;
        loop
        fetch jv into jv_actcode,jv_dramount,jv_cramount, jv_ref_no;
        exit when jv%notfound;

            select parent, lvl, actname
            into v_parent, v_lvl, v_actname
            from pm_accounts
            where actcode = jv_actcode;

            select getSuperParent(v_actname)
            into v_superparent
            from dual;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

                update pm_journaldl
                set balance = balance - jv_dramount + jv_cramount
                where actcode = jv_actcode
                and journalno > (select journalno from pm_journaldl where ref_no = jv_ref_no);

                delete from pm_journaldl
                where ref_no = jv_ref_no;

                select nvl(max(nvl(journalno,0)),0)
                into v_journalno
                from pm_journaldl
                where vdate <= :new.vdate;

                select count(*)
                into v_c
                from pm_journaldl
                where actcode = jv_actcode
                and vdate <= :new.vdate;

                if v_c > 0 then

                    select balance
                    into v_balance
                    from pm_journaldl
                    where actcode = jv_actcode
                    and journalno = (select max(journalno) from pm_journaldl where actcode = jv_actcode
                                        and vdate <= :new.vdate);

                else

                    v_balance := 0;

                end if;

                update pm_journaldl set balance = balance + jv_dramount - jv_cramount
                where journalno > v_journalno
                and actcode = jv_actcode;

                update pm_journaldl set journalno = journalno + 1
                where journalno > v_journalno;

                insert into pm_journaldl(voucherno, vdate, actcode, actname,
                dramount, cramount, balance, journalno, ref_no)
                values ( :new.voucherno, :new.vdate, jv_actcode, v_actname,
                jv_dramount, jv_cramount,v_balance + jv_dramount - jv_cramount,
                v_journalno+1, jv_ref_no);

                if v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability') then

                    dbms_output.put_line(v_opening_date||' to '||v_closing_date);
                    pfCalc(v_opening_date, v_closing_date);

                end if;

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance - jv_dramount + jv_cramount
                where actcode = jv_actcode
                and journalno > (select journalno from pm_journaldl where ref_no = jv_ref_no)
                and vdate <= v_closing_date;

                delete from pm_journaldl
                where ref_no = jv_ref_no;

                select nvl(max(nvl(journalno,0)),0)
                into v_journalno
                from pm_journaldl
                where vdate <= :new.vdate;

                select count(*)
                into v_c
                from pm_journaldl
                where actcode = jv_actcode
                and vdate <= :new.vdate;

                if v_c > 0 then

                    select balance
                    into v_balance
                    from pm_journaldl
                    where actcode = jv_actcode
                    and journalno = (select max(journalno) from pm_journaldl where actcode = jv_actcode
                                        and vdate <= :new.vdate);

                else

                    v_balance := 0;

                end if;

                update pm_journaldl set balance = balance + jv_dramount - jv_cramount
                where journalno > v_journalno
                and actcode = jv_actcode
                and vdate <= v_closing_date;

                update pm_journaldl set journalno = journalno + 1
                where journalno > v_journalno;

                insert into pm_journaldl(voucherno, vdate, actcode, actname,
                dramount, cramount, balance, journalno, ref_no)
                values ( :new.voucherno, :new.vdate, jv_actcode, v_actname,
                jv_dramount, jv_cramount,v_balance + jv_dramount - jv_cramount,
                v_journalno+1, jv_ref_no);

            end if;

        end loop;
        close jv;

    end if;

end;
/


CREATE OR REPLACE TRIGGER GL.op_insert
AFTER INSERT ON pm_opening_balance
FOR EACH ROW
DECLARE

    v_voucher    pm_journal_voucher.voucherno%type;
    v_date        date;

BEGIN

    select count(voucherno)
    into v_voucher
    from pm_journal_voucher
    where voucherno = :new.voucherno;

    if v_voucher = 0 then

        select op_date
        into v_date
        from pm_opening_master
        where voucherno = :new.voucherno;

        INSERT INTO    pm_journal_voucher(voucherno,vdate,flag)
        VALUES        (:new.voucherno,v_date,'N');
    end if;


    INSERT INTO     pm_journal_jv(itemno,actcode,dramount,cramount,voucherno)
    VALUES        (:new.itemno, :new.actcode, :new.balancedr, :new.balancecr,
            :new.voucherno);

END;
/


