CREATE OR REPLACE TRIGGER GL.voucher_master_update
after update of vdate, vtype on pm_voucher
for each row
declare

        CURSOR v is select actcode, nvl(amount,0), ref_no from pm_voucher_item where voucherno = :new.voucherno;

        v_total_amount        number(32,2) := 0;
        v_actcode            varchar2(200);
        v_amount            number(32,2);
        v_ref_no            number(32);
        v_balance            number(32,2);
        v_journalno            number(32);
        v_c                    number(32);
        v_cash_actname        varchar2(200) := 'HeadOffice Cash In Hand';
        v_actname            varchar2(200);
        v_closing_date        date;
        v_opening_date        date;
        v_closed            char(3);
        v_superparent        varchar2(200);

begin

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    open v;
    loop
    fetch v into v_actcode, v_amount, v_ref_no;
    exit when v%notfound;

        select actname into v_actname from pm_accounts where actcode = v_actcode;

        select getSuperParent(v_actname)
        into v_superparent
        from dual;

        v_total_amount := v_total_amount + v_amount;

        if :new.vdate = :old.vdate then

            if :new.vtype <> :old.vtype then

                if :new.vtype = 'ccv' then

                    update pm_journaldl
                    set cramount = v_amount,dramount = 0,
                    balance = balance - 2*v_amount
                    where ref_no = v_ref_no;

                    if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                        update pm_journaldl
                        set balance = balance - 2*v_amount
                        where actcode = v_actcode
                        and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no);

                    elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                        update pm_journaldl
                        set balance = balance - 2*v_amount
                        where actcode = v_actcode
                        and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no)
                        and vdate <= v_closing_date;

                    end if;

                elsif :new.vtype = 'cdv' then

                    update pm_journaldl
                    set dramount = v_amount,cramount = 0,
                    balance = balance + 2*v_amount
                    where ref_no = v_ref_no;

                    if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                        update pm_journaldl
                        set balance = balance + 2*v_amount
                        where actcode = v_actcode
                        and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no);

                    elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                        update pm_journaldl
                        set balance = balance + 2*v_amount
                        where actcode = v_actcode
                        and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no)
                        and vdate <= v_closing_date;

                    end if;

                end if;

            end if;

        elsif :new.vdate <> :old.vdate then

            if :old.vtype = 'ccv' then

                if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                    update pm_journaldl
                    set balance = balance + v_amount
                    where actcode = v_actcode
                    and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no);

                elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                    update pm_journaldl
                    set balance = balance + v_amount
                    where actcode = v_actcode
                    and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no)
                    and vdate <= v_closing_date;

                end if;

            elsif :old.vtype = 'cdv' then

                if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                    update pm_journaldl
                    set balance = balance - v_amount
                    where actcode = v_actcode
                    and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no);

                elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                    update pm_journaldl
                    set balance = balance - v_amount
                    where actcode = v_actcode
                    and journalno > (select journalno from pm_journaldl where ref_no = v_ref_no)
                    and vdate <= v_closing_date;

                end if;

            end if;

            delete from pm_journaldl where ref_no = v_ref_no;

            select nvl(max(nvl(journalno,0)),0)
            into v_journalno
            from pm_journaldl
            where vdate <= :new.vdate;

            select count(*)
            into v_c
            from pm_journaldl
            where actcode = v_actcode
            and vdate <= :new.vdate;

            if v_c > 0 then

                select balance
                into v_balance
                from pm_journaldl
                where actcode = v_actcode
                and journalno = (select max(journalno) from pm_journaldl where actcode = v_actcode
                                and vdate <= :new.vdate);

            else

                v_balance := 0;

            end if;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                if :new.vtype = 'ccv' then

                    update pm_journaldl
                    set balance = balance - v_amount
                    where actcode = v_actcode
                    and journalno > v_journalno;

                elsif :new.vtype = 'cdv' then

                    update pm_journaldl
                    set balance = balance + v_amount
                    where actcode = v_actcode
                    and journalno > v_journalno;

                end if;

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                if :new.vtype = 'ccv' then

                    update pm_journaldl
                    set balance = balance - v_amount
                    where actcode = v_actcode
                    and journalno > v_journalno
                    and vdate <= v_closing_date;

                elsif :new.vtype = 'cdv' then

                    update pm_journaldl
                    set balance = balance + v_amount
                    where actcode = v_actcode
                    and journalno > v_journalno
                    and vdate <= v_closing_date;

                end if;

            end if;

            update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

            if :new.vtype = 'ccv' then

                insert into pm_journaldl(voucherno, vdate, actcode, actname,
                dramount, cramount, balance, journalno, ref_no)
                values ( :new.voucherno, :new.vdate, v_actcode, v_actname,
                0,nvl(v_amount,0),v_balance - v_amount,v_journalno+1, v_ref_no);

            elsif :new.vtype = 'cdv' then

                insert into pm_journaldl(voucherno, vdate, actcode, actname,
                dramount, cramount, balance, journalno, ref_no)
                values ( :new.voucherno, :new.vdate, v_actcode, v_actname,
                nvl(v_amount,0),0,v_balance + v_amount,v_journalno+1, v_ref_no);

            end if;

        end if;

    end loop;
    close v;


    /************************************* FOR CASH ***************************************************************/

    if :new.vdate <> :old.vdate then

        if :old.vtype = 'ccv' then

            update pm_journaldl
            set balance = balance - v_total_amount
            where actcode = :new.actcode
            and journalno > (select journalno from pm_journaldl where ref_no = :new.cash_ref_no);

        elsif :old.vtype = 'cdv' then

            update pm_journaldl
            set balance = balance + v_total_amount
            where actcode = :new.actcode
            and journalno > (select journalno from pm_journaldl where ref_no = :new.cash_ref_no);

        end if;

        delete from pm_journaldl where ref_no = :new.cash_ref_no;

        select nvl(max(nvl(journalno,0)),0)
        into v_journalno
        from pm_journaldl
        where vdate <= :new.vdate;

        select count(*)
        into v_c
        from pm_journaldl
        where actcode = :new.actcode
        and vdate <= :new.vdate;

        if v_c > 0 then

            select balance
            into v_balance
            from pm_journaldl
            where actcode = :new.actcode
            and journalno = (select max(journalno) from pm_journaldl where actcode = :new.actcode
                            and vdate <= :new.vdate);

        else

            v_balance := 0;

        end if;

        if :new.vtype = 'ccv' then

            update pm_journaldl
            set balance = balance + v_total_amount
            where actcode = :new.actcode
            and journalno > v_journalno;

        elsif :new.vtype = 'cdv' then

            update pm_journaldl
            set balance = balance - v_total_amount
            where actcode = :new.actcode
            and journalno > v_journalno;

        end if;

        update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

        if :new.vtype = 'ccv' then

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, :new.vdate, :new.actcode, v_cash_actname,
            nvl(v_total_amount,0),0,v_balance + v_total_amount,v_journalno+1, :new.cash_ref_no);

        elsif :new.vtype = 'cdv' then

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, :new.vdate, :new.actcode, v_cash_actname,
            0,nvl(v_total_amount,0),v_balance - v_total_amount,v_journalno+1, :new.cash_ref_no);

        end if;

    elsif :old.vdate = :new.vdate then

        if :new.vtype <> :old.vtype then

            if :new.vtype = 'ccv' then

                update pm_journaldl
                set dramount = v_total_amount,cramount = 0,
                balance = balance + 2*v_total_amount
                where ref_no = :new.cash_ref_no;

                update pm_journaldl
                set balance = balance + 2*v_total_amount
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.cash_ref_no);

            elsif :new.vtype = 'cdv' then

                update pm_journaldl
                set cramount = v_total_amount,dramount = 0,
                balance = balance - 2*v_total_amount
                where ref_no = :new.cash_ref_no;

                update pm_journaldl
                set balance = balance - 2*v_total_amount
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.cash_ref_no);

            end if;

        end if;

    end if;

    if v_closed = 'YES' then

        dbms_output.put_line(v_opening_date||' to '||v_closing_date);
        pfCalc(v_opening_date, v_closing_date);

    end if;

end;
/


CREATE OR REPLACE TRIGGER GL.voucher_item_delete
after delete on pm_voucher_item
for each row
declare

    v_vtype            varchar2(200);
    v_cash_ref_no    number(32);
    v_cash_actcode    varchar2(200);
    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);
    v_actname            varchar2(200);


begin

        select startdate, enddate,closed
        into v_opening_date, v_closing_date, v_closed
        from finyear
        where curuse = 'YES';

        select vtype, cash_ref_no, actcode
        into v_vtype, v_cash_ref_no, v_cash_actcode
        from pm_voucher
        where voucherno = :old.voucherno;

        select actname
        into v_actname
        from  pm_accounts
        where actcode = :old.actcode;

        select getSuperParent(v_actname)
        into v_superparent
        from dual;

        if v_vtype = 'ccv' then

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                update pm_journaldl
                set balance = balance + nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no);

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance + nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no)
                and vdate <= v_closing_date;

            end if;

            update pm_journaldl
            set balance = balance - nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno > (select journalno from pm_journaldl where ref_no = v_cash_ref_no);

            update pm_journaldl
            set dramount = dramount - nvl(:old.amount,0),
            balance = balance - nvl(:old.amount,0)
            where ref_no = v_cash_ref_no;

        elsif v_vtype = 'cdv' then

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability')) then

                update pm_journaldl
                set balance = balance - nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no);

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance - nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :old.ref_no)
                and vdate <= v_closing_date;

            end if;

            update pm_journaldl
            set balance = balance + nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno > (select journalno from pm_journaldl where ref_no = v_cash_ref_no);

            update pm_journaldl
            set cramount = cramount - nvl(:old.amount,0),
            balance = balance + nvl(:old.amount,0)
            where ref_no = v_cash_ref_no;

        end if;

        delete from pm_journaldl where ref_no = :old.ref_no;

        if v_closed = 'YES' then

            dbms_output.put_line(v_opening_date||' to '||v_closing_date);
            pfCalc(v_opening_date, v_closing_date);

        end if;
end;
/


CREATE OR REPLACE TRIGGER GL.voucher
after insert on pm_voucher_item
for each row
declare

    v_parent                pm_accounts.parent%type;
    v_cash_parent            pm_accounts.parent%type;
    v_lvl                    pm_accounts.lvl%type;
    v_cash_lvl                pm_accounts.lvl%type;
    v_actname                pm_accounts.actname%type;
    v_cash_actname            pm_accounts.actname%type;
    v_vdate                    date;
    v_vtype                    pm_voucher.vtype%type;
    v_balance                pm_journaldl.balance%type:=0;
    v_cash_balance            pm_journaldl.balance%type:=0;
    v_count                    number(32);
    v_cash_actcode            pm_accounts.actcode%type;
    v_balance_count            number(32);
    v_balance_count_cash    number(32);
    v_max_journalno            number(32);
    v_voucher_count            number(32);
    v_max_cash_journalno    number(32);
    v_cash_ref_no            number(32);
    v_closing_date            date;
    v_opening_date            date;
    v_closed                char(3);
    v_superparent            varchar2(200);

begin
    -- for new head of accounts

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    select parent, lvl, actname
    into v_parent, v_lvl, v_actname
    from pm_accounts
    where actcode = :new.actcode;

    select getSuperParent(v_actname)
    into v_superparent
    from dual;

    select vdate,vtype,actcode, cash_ref_no
    into v_vdate, v_vtype, v_cash_actcode, v_cash_ref_no
    from pm_voucher
    where voucherno = :new.voucherno;

    --- for Cash in hand

    select actname, parent, lvl
    into v_cash_actname, v_cash_parent, v_cash_lvl
    from pm_accounts
    where actcode = v_cash_actcode;

    select count(*)
    into v_balance_count
    from pm_journaldl
    where actcode = :new.actcode
    and vdate  <= v_vdate;

    select nvl(max(nvl(journalno,0)),0)
    into v_max_journalno
    from pm_journaldl
    where vdate <= v_vdate;

    update pm_journaldl set journalno = journalno + 2
    where journalno > v_max_journalno;

    if v_balance_count > 0 then

        select balance
        into v_balance
        from pm_journaldl
        where actcode = :new.actcode
        and journalno =
            (select max(journalno)
            from pm_journaldl
            where actcode = :new.actcode
            and vdate <= v_vdate);
    end if;

    ---- getting cash balance

    select count(*)
    into v_balance_count_cash
    from pm_journaldl
    where actcode = v_cash_actcode
    and vdate <= v_vdate;


    if v_balance_count_cash > 0 then

        select balance
        into v_cash_balance
        from pm_journaldl
        where actcode = v_cash_actcode
        and journalno =
            (select max(journalno)
            from pm_journaldl
            where actcode = v_cash_actcode
            and vdate <= v_vdate);
    end if;

    if v_vtype = 'ccv' then

        --- inserting for head of accounts

        if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

            update pm_journaldl set balance = balance - :new.amount
            where journalno > v_max_journalno
            and actcode = :new.actcode;

        elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

            update pm_journaldl set balance = balance - :new.amount
            where journalno > v_max_journalno
            and actcode = :new.actcode
            and vdate <= v_closing_date;

        end if;

        insert into pm_journaldl(voucherno, vdate, actcode, actname, source,
        dramount, cramount, balance, journalno, ref_no)
        values ( :new.voucherno, v_vdate, :new.actcode, v_actname,'CCV',
        0, :new.amount, v_balance - :new.amount, v_max_journalno+1, :new.ref_no);

        ---- inserting for cash

        select count(*)
        into v_voucher_count
        from pm_journaldl
        where voucherno = :new.voucherno
        and actcode = v_cash_actcode;

        if v_voucher_count > 0 then

            update pm_journaldl set dramount = dramount + :new.amount,
            balance = balance + :new.amount
            where voucherno = :new.voucherno
            and actcode = v_cash_actcode;

            update pm_journaldl set balance = balance + :new.amount
            where journalno > (select journalno from pm_journaldl
                       where actcode = v_cash_actcode
                       and voucherno = :new.voucherno)
            and actcode = v_cash_actcode;

        else

            update pm_journaldl set balance = balance + :new.amount
            where journalno > v_max_journalno
            and actcode = v_cash_actcode;

            insert into pm_journaldl(voucherno, vdate, actcode, actname, source,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, v_cash_actcode, v_cash_actname,'CCV',
            :new.amount, 0, v_cash_balance + :new.amount, v_max_journalno+2, v_cash_ref_no);

        end if;

    elsif v_vtype = 'cdv' then

        --- inserting for head of accounts

        if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

            update pm_journaldl set balance = balance + :new.amount
            where journalno > v_max_journalno
            and actcode = :new.actcode;

        elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

            update pm_journaldl set balance = balance + :new.amount
            where journalno > v_max_journalno
            and actcode = :new.actcode
            and vdate <= v_closing_date;

        end if;

        insert into pm_journaldl(voucherno, vdate, actcode, actname, source,
        dramount, cramount, balance, journalno, ref_no)
        values ( :new.voucherno, v_vdate, :new.actcode, v_actname,'CDV',
        :new.amount, 0, v_balance + :new.amount, v_max_journalno+1, :new.ref_no);

        ---- inserting for cash

        select count(*)
        into v_voucher_count
        from pm_journaldl
        where voucherno = :new.voucherno
        and actcode = v_cash_actcode;

        if v_voucher_count > 0 then

            update pm_journaldl set cramount = cramount + :new.amount,
            balance = balance - :new.amount
            where voucherno = :new.voucherno
            and actcode = v_cash_actcode;

            update pm_journaldl set balance = balance - :new.amount
            where journalno > (select journalno from pm_journaldl
                       where actcode = v_cash_actcode
                       and voucherno = :new.voucherno)
            and actcode = v_cash_actcode;

        else

            update pm_journaldl set balance = balance - :new.amount
            where journalno > v_max_journalno
            and actcode = v_cash_actcode;

            insert into pm_journaldl(voucherno, vdate, actcode, actname, source,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, v_cash_actcode, v_cash_actname,'CDV',
            0, :new.amount, v_cash_balance - :new.amount, v_max_journalno+2, v_cash_ref_no);

        end if;

    end if;

    if v_closed = 'YES' then

        dbms_output.put_line(v_opening_date||' to '||v_closing_date);
        pfCalc(v_opening_date, v_closing_date);

    end if;


end;
/


CREATE OR REPLACE TRIGGER GL.voucher_update
after update on pm_voucher_item
for each row
declare

    v_parent            pm_accounts.parent%type;
    v_cash_parent        pm_accounts.parent%type;
    v_lvl                pm_accounts.lvl%type;
    v_cash_lvl            pm_accounts.lvl%type;
    v_actname            pm_accounts.actname%type;
    v_cash_actname        pm_accounts.actname%type;
    v_vdate                date;
    v_vtype                pm_voucher.vtype%type;
    v_balance            pm_journaldl.balance%type:=0;
    v_cash_actcode        varchar2(200);
    v_cash_ref_no        number(32);
    v_c                    number(32);
    v_journalno            number(32);
    v_cash_journalno    number(32);
    v_closing_date        date;
    v_opening_date        date;
    v_closed            char(3);
    v_superparent        varchar2(200);
    v_oldactname        varchar2(200);
    v_oldsuperparent    varchar2(200);

begin

    select startdate, enddate,closed
    into v_opening_date, v_closing_date, v_closed
    from finyear
    where curuse = 'YES';

    select parent, lvl, actname
    into v_parent, v_lvl, v_actname
    from pm_accounts
    where actcode = :new.actcode;

    select actname
    into v_oldactname
    from pm_accounts
    where actcode = :old.actcode;

    select getSuperParent(v_actname)
    into v_superparent
    from dual;

    select getSuperParent(v_oldactname)
    into v_oldsuperparent
    from dual;

    select vdate,vtype, actcode, cash_ref_no
    into v_vdate, v_vtype, v_cash_actcode, v_cash_ref_no
    from pm_voucher
    where voucherno = :new.voucherno;

    select parent, lvl, actname
    into v_cash_parent, v_cash_lvl, v_cash_actname
    from pm_accounts
    where actcode = v_cash_actcode;

    dbms_output.put_line(v_vtype);

    if :new.actcode <> :old.actcode then

        if v_vtype = 'ccv' then

            if v_closed = 'NO' or (v_closed = 'YES' and (v_oldsuperparent = 'Asset' or v_oldsuperparent = 'Liability'))then

                update pm_journaldl
                set balance = balance + nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no);

            elsif v_closed = 'YES' and (v_oldsuperparent = 'Revenue' or v_oldsuperparent = 'Expense') then

                update pm_journaldl
                set balance = balance + nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no)
                and vdate <= v_closing_date;

            end if;

            delete from pm_journaldl where ref_no = :new.ref_no;

            select nvl(max(nvl(journalno,0)),0)
            into v_journalno
            from pm_journaldl
            where vdate <= v_vdate;

            select count(*)
            into v_c
            from pm_journaldl
            where actcode = :new.actcode
            and vdate <= v_vdate;

            if v_c > 0 then

                select balance
                into v_balance
                from pm_journaldl
                where actcode = :new.actcode
                and journalno = (select max(journalno) from pm_journaldl where actcode = :new.actcode
                                    and vdate <= v_vdate);

            else

                v_balance := 0;

            end if;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

                update pm_journaldl
                set balance = balance - nvl(:new.amount,0)
                where actcode = :new.actcode
                and journalno > v_journalno;

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance - nvl(:new.amount,0)
                where actcode = :new.actcode
                and journalno > v_journalno
                and vdate <= v_closing_date;

            end if;

            update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
            0, nvl(:new.amount,0),v_balance - nvl(:new.amount,0),
            v_journalno+1, :new.ref_no);

            select journalno
            into v_cash_journalno

            from pm_journaldl
            where ref_no = v_cash_ref_no;

            update pm_journaldl
            set dramount = dramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno = v_cash_journalno;

            update pm_journaldl
            set balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno > v_cash_journalno;

        elsif v_vtype = 'cdv' then

            if v_closed = 'NO' or (v_closed = 'YES' and (v_oldsuperparent = 'Asset' or v_oldsuperparent = 'Liability'))then

                update pm_journaldl
                set balance = balance - nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no);

            elsif v_closed = 'YES' and (v_oldsuperparent = 'Revenue' or v_oldsuperparent = 'Expense') then

                update pm_journaldl
                set balance = balance - nvl(:old.amount,0)
                where actcode = :old.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no)
                and vdate <= v_closing_date;

            end if;

            delete from pm_journaldl where ref_no = :new.ref_no;

            select nvl(max(nvl(journalno,0)),0)
            into v_journalno
            from pm_journaldl
            where vdate <= v_vdate;

            select count(*)
            into v_c
            from pm_journaldl
            where actcode = :new.actcode
            and vdate <= v_vdate;

            if v_c > 0 then

                select balance
                into v_balance
                from pm_journaldl
                where actcode = :new.actcode
                and journalno = (select max(journalno) from pm_journaldl where actcode = :new.actcode
                                    and vdate <= v_vdate);

            else

                v_balance := 0;

            end if;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

                update pm_journaldl
                set balance = balance + nvl(:new.amount,0)
                where actcode = :new.actcode
                and journalno > v_journalno;

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance + nvl(:new.amount,0)
                where actcode = :new.actcode
                and journalno > v_journalno
                and vdate <= v_closing_date;

            end if;

            update pm_journaldl set journalno = journalno + 1 where journalno > v_journalno;

            insert into pm_journaldl(voucherno, vdate, actcode, actname,
            dramount, cramount, balance, journalno, ref_no)
            values ( :new.voucherno, v_vdate, :new.actcode, v_actname,
            nvl(:new.amount,0),0,v_balance + nvl(:new.amount,0),
            v_journalno+1, :new.ref_no);

            select journalno
            into v_cash_journalno
            from pm_journaldl
            where ref_no = v_cash_ref_no;

            update pm_journaldl
            set cramount = cramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
            where actcode = v_cash_actcode
            and journalno = v_cash_journalno;

            update pm_journaldl
            set balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
            where actcode = v_cash_actcode
            and journalno > v_cash_journalno;

        end if;

    elsif :new.actcode = :old.actcode then

        if v_vtype = 'ccv' then

            update pm_journaldl
            set cramount = cramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
            where ref_no = :new.ref_no;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

                update pm_journaldl
                set balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no);

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no)
                and vdate <= v_closing_date;

            end if;

            select journalno
            into v_cash_journalno
            from pm_journaldl
            where ref_no = v_cash_ref_no;

            update pm_journaldl
            set dramount = dramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno = v_cash_journalno;

            update pm_journaldl
            set balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
            where actcode = v_cash_actcode
            and journalno > v_cash_journalno;

        elsif v_vtype = 'cdv' then

            update pm_journaldl
            set dramount = dramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
            where ref_no = :new.ref_no;

            if v_closed = 'NO' or (v_closed = 'YES' and (v_superparent = 'Asset' or v_superparent = 'Liability'))then

                update pm_journaldl
                set balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no);

            elsif v_closed = 'YES' and (v_superparent = 'Revenue' or v_superparent = 'Expense') then

                update pm_journaldl
                set balance = balance + nvl(:new.amount,0) - nvl(:old.amount,0)
                where actcode = :new.actcode
                and journalno > (select journalno from pm_journaldl where ref_no = :new.ref_no)
                and vdate <= v_closing_date;

            end if;

            select journalno
            into v_cash_journalno
            from pm_journaldl
            where ref_no = v_cash_ref_no;

            update pm_journaldl
            set cramount = cramount + nvl(:new.amount,0) - nvl(:old.amount,0),
            balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
            where actcode = v_cash_actcode
            and journalno = v_cash_journalno;

            update pm_journaldl
            set balance = balance - (nvl(:new.amount,0) - nvl(:old.amount,0))
            where actcode = v_cash_actcode
            and journalno > v_cash_journalno;

        end if;

    end if;

    if v_closed = 'YES' then

        dbms_output.put_line(v_opening_date||' to '||v_closing_date);
        pfCalc(v_opening_date, v_closing_date);

    end if;


end;
/


CREATE OR REPLACE TRIGGER GL.post_sal_other
after update of posted on sal_sheetm
for each row
declare
    -----------------------------
    CURSOR lwpc is select  slno
            from lwpregd
        WHERE     (
                (flag is null AND frm_date >= :new.last_gen_date and to_date <= :new.gen_date)
                OR (lwp_up is not null and lwp_up <> 0 )
            );
    ------------------------------

    -----------------------------
    CURSOR slc is select  slno
            from leaveregd
        WHERE sl is not null
        AND  (
            (flag is null AND  frm_date >= :new.last_gen_date and to_date <= :new.gen_date)
            OR (sl_up is not null and sl_up <> 0)
             );
    ------------------------------

    -----------------------------
    CURSOR loanc is select  loanid FROM loan
        WHERE loan_balance>0
        AND (starting_date <= :new.gen_date and flag='N' and suspend<>'Y');
    ------------------------------

    v_lwp_slno     number(32);
    v_sl_slno    number(32);
    v_loanid    number(32);

begin
    if :new.posted='Y' then

    open lwpc;
    loop
    fetch lwpc
        into v_lwp_slno;

    exit when lwpc%notfound;

        UPDATE lwpregd
        SET flag='Y'
        WHERE flag is null AND slno=v_lwp_slno;

        UPDATE lwpregd
        SET lwp_up =0
        WHERE flag is null AND slno=v_lwp_slno
        AND lwp_up <> 0;
    end loop;
    close lwpc;

    open SLC;
    loop
    fetch SLC
        into v_sl_slno;

    exit when slc%notfound;

        UPDATE leaveregd
        SET flag='Y'
        WHERE flag is null AND slno=v_sl_slno;

        UPDATE leaveregd
        SET sl_up =0
        WHERE flag is null AND slno=v_sl_slno
        AND sl_up <> 0;

    end loop;
    close slc;


        /*** Update Loan Table if loan_bal = 0 ( means loan is cleared )**/

    open loanc;
    loop
    fetch loanc
        into v_loanid;

    exit when loanc%notfound;

        update loan set loan_balance = loan_balance - installment where loanid= v_loanid;

    end loop;
    close loanc;

    update loan set flag='Y', loan_balance=0 where loan_balance<=0;

    end if; -- end of posted='Y'
end;
/


CREATE OR REPLACE TRIGGER GL.post_sal_acc
after update of posted on sal_sheetm
for each row
declare

    v_tsal_off    number(32,4);
    v_tsal_fac    number(32,4);
    v_tsal_wag    number(32,4);
    v_cash        varchar2(200);
    v_off_code    varchar2(200);
    v_id        number(32);
    v_inst        number(32,4);
    --v_tot_adv    number(32,4);
    v_actcode    varchar2(200);
    v_count        number(32) :=1;
    v_sal_code    varchar2(200);
    v_lwpno     number;
    v_lno        number;
    v_loanid    number;
    brbact_cash varchar2(200);
    brbact_sal  varchar2(200);
    v_voucherno   number;
    /*------------------------------------------------
    CURSOR    adv is select empid,installment
            from loan
            where loan_balance > 0 and starting_date <= :new.gen_date;
    ------------------------------------------------*/
    -----------------------------
    CURSOR lwpc is select lwpno FROM lwpregd
        WHERE (flag is null and frm_date <= :new.gen_date and to_date <= :new.gen_date)
        OR (lwp_up is not null and lwp_up <> 0 );
    ------------------------------

    -----------------------------
    CURSOR slc is select  lno FROM leaveregd
        WHERE sl is not null
        AND (flag is null and frm_date <= :new.gen_date and to_date <= :new.gen_date)
        OR (sl_up is not null and sl_up <> 0);
    ------------------------------

    -----------------------------
    CURSOR loanc is select  loanid FROM loan
        WHERE loan_balance>0
        AND (starting_date < :new.gen_date );
    ------------------------------

begin

    /** create voucher no from sequence postsal_sq_sq **/

    if :new.posted = 'Y' then

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------1');

        /*********Totalling the amount for those in Office********/
        select sum(nvl((gross_sal-nvl(gross_sal_ded,0)),0))
        into v_tsal_off
        from sal_sheetd
        where salaryno = :new.salaryno
        and empid in (select empid
                from emp
                where staff_type = 'Office');

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------2');

        /*********Totalling the amount for those in Factory********/
        select sum(nvl((gross_sal-nvl(gross_sal_ded,0)),0))
        into v_tsal_fac
        from sal_sheetd
        where salaryno = :new.salaryno
        and empid in (select empid
                from emp
                where staff_type = 'Factory');

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------3');

        /*********Totalling the amount for those in Wages********/
        select sum(nvl((gross_sal-nvl(gross_sal_ded,0)),0))
        into v_tsal_wag
        from sal_sheetd
        where salaryno = :new.salaryno
        and empid in (select empid
                from emp
                where staff_type = 'Wages');


        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------4');

        select actcode
        into v_cash
        from pm_Accounts
        where actname = 'HeadOffice Cash In Hand';

    ------------------
        /*******Creating voucher for SALARY**********************/
        insert into pm_voucher (voucherno, vdate, actcode, vtype, total_amount,Description,cash_ref_no)
        values ('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,v_cash,'cdv',nvl(v_tsal_off,0),'Salary',refno_sq.nextval);


        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------5');

        select actcode
        into v_off_code
        from pm_accounts
        where actname = 'Salary';

        insert into pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
        values(1,'CVPR'||TO_CHAR(postsal_sq.currval),nvl(v_tsal_off,0),v_off_code,refno_Sq.nextval);

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------6');


/***********************************   FOR POSRING INTO ACTUAL ***************/

        select actcode
        into brbact_sal
        from brbact.pm_Accounts
        where actname = 'salary';

        select count(voucherno)
        into v_voucherno
        from brbact.pm_voucher
        where description = 'Salary'
        and vdate = :new.gen_date;

        select actcode
        into brbact_cash
        from brbact.pm_Accounts
        where actname = 'HeadOffice Cash In Hand';

        if v_voucherno > 0 then

            update brbact.pm_voucher_item set amount = amount + nvl(v_tsal_off,0)
            where voucherno = (select voucherno from brbact.pm_voucher where vdate = :new.gen_date and description = 'Salary');

        else
            insert into brbact.pm_voucher (voucherno, vdate, actcode, vtype, total_amount,Description,cash_ref_no)
                values ('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,brbact_cash,'cdv',nvl(v_tsal_off,0),'Salary',brbact.refno_Sq.nextval);

            insert into brbact.pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
            values(1,'CVPR'||TO_CHAR(postsal_sq.currval),nvl(v_tsal_off,0),brbact_sal,brbact.refno_sq.nextval);

        end if;








    ------------------------

        /*******Creating voucher for FACTORY**********************/
        insert into pm_voucher(voucherno,vdate,actcode,vtype,total_amount,Description,cash_ref_no)
        values('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,v_cash,'cdv',nvl(v_tsal_fac,0),'Salary For Factory',refno_sq.nextval);

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------6a');

        select actcode
        into v_sal_code
        from pm_accounts
        where actname = 'Salary For Factory';

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------6b');

        insert into pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
        values(1,'CVPR'||to_char(postsal_sq.currval),nvl(v_tsal_fac,0),v_sal_code,refno_Sq.nextval);

        DBMS_OUTPUT.PUT_LINE ('TESTTTTT--------7');


/****************  For POSTING INTO ACTUAL  *********************/

        brbact_sal := null;

        select actcode
        into brbact_sal
        from brbact.pm_Accounts
        where actname = 'Salary for Factory';

        select count(voucherno)
        into v_voucherno
        from brbact.pm_voucher
        where description = 'Salary For Factory'
        and vdate = :new.gen_date;


        if v_voucherno > 0 then

            update brbact.pm_voucher_item set amount = amount + nvl(v_tsal_fac,0)
            where voucherno = (select voucherno from brbact.pm_voucher where vdate = :new.gen_date and description = 'Salary For Factory');

        else
            insert into brbact.pm_voucher (voucherno, vdate, actcode, vtype, total_amount,Description,cash_ref_no)
                values ('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,brbact_cash,'cdv',nvl(v_tsal_fac,0),'Salary For Factory',brbact.refno_sq.nextval);

            insert into brbact.pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
            values(1,'CVPR'||TO_CHAR(postsal_sq.currval),nvl(v_tsal_fac,0),brbact_sal,brbact.refno_sq.nextval);

        end if;


    ------------------------

        /*******Creating voucher for WAGES**********************/
        insert into pm_voucher(voucherno,vdate,actcode,vtype,total_amount,Description,cash_ref_no)
        values('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,v_cash,'cdv',nvl(v_tsal_wag,0),'Wages',refno_sq.nextval);


        select actcode
        into v_off_code
        from pm_accounts
        where actname = 'Wages';


        insert into pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
        values(1,'CVPR'||to_char(postsal_sq.currval),nvl(v_tsal_wag,0),v_off_code,refno_Sq.nextval);

        /****************  For POSTING INTO ACTUAL  *********************/

                brbact_sal := null;

                select actcode
                into brbact_sal
                from brbact.pm_Accounts
                where actname = 'Wages';

                select count(voucherno)
                into v_voucherno
                from brbact.pm_voucher
                where description = 'Wages'
                and vdate = :new.gen_date;


                if v_voucherno > 0 then

                    update brbact.pm_voucher_item set amount = amount + nvl(v_tsal_wag,0)
                    where voucherno = (select voucherno from brbact.pm_voucher where vdate = :new.gen_date and description = 'Wages');

                else
                    insert into brbact.pm_voucher (voucherno, vdate, actcode, vtype, total_amount,Description,cash_ref_no)
                        values ('CVPR'||TO_CHAR(postsal_sq.nextval),:new.gen_date,brbact_cash,'cdv',nvl(v_tsal_wag,0),'Wages',brbact.refno_Sq.nextval);

                    insert into brbact.pm_voucher_item(itemno,voucherno,amount,actcode,ref_no)
                    values(1,'CVPR'||TO_CHAR(postsal_sq.currval),nvl(v_tsal_wag,0),brbact_sal,brbact.refno_Sq.nextval);

        end if;

    -------------------------

    /*

    --*********Handling ADVANCE**************--

      select sum(nvl(installment,0))
        into v_tot_adv
        from loan
        where loan_balance > 0 and starting_date <= :new.gen_date;

        if v_tot_adv > 0 then

            insert into pm_voucher(voucherno,vdate,actcode,vtype,total_amount)
                values('CVHL'||TO_CHAR(postsal_sq.nextval),:new.gen_date,v_cash,'ccv',v_tot_adv);

            v_count :=1;
            open adv;
            loop
            fetch adv into v_id,v_inst;

            exit when adv%notfound;


                select actcode
                into v_actcode
                from pm_accounts
                where accid =  (select accid
                        from emp
                        where empid = v_id);


            insert into pm_voucher_item(itemno,voucherno,amount,actcode)
                values(v_count,'CVHL'||to_char(postsal_sq.currval),v_inst,v_actcode);

            v_count := v_count+1;

            end loop;
            close adv;
        end if;
    */

    end if;


    /********************************* Do things othet than accounts ********************/
    /******** loan , lwp, sl ...... ****************************************************/

    open lwpc;
    loop
    fetch lwpc
        into v_lwpno;

    exit when lwpc%notfound;

        UPDATE lwpregd
        SET flag='Y'
        WHERE flag is null and frm_date <= :new.gen_date AND to_date <= :new.gen_date
        AND lwpno=v_lwpno;

        UPDATE lwpregd
        SET lwp_up =0
        WHERE lwp_up <> 0 and  frm_date <= :new.gen_date AND to_date <= :new.gen_date
        AND lwpno=v_lwpno;
    end loop;
    close lwpc;

    open SLC;
    loop
    fetch SLC
        into v_lno;

    exit when slc%notfound;

        UPDATE leaveregd
        SET flag='Y'
        WHERE flag is null AND frm_date <= :new.gen_date AND to_date <= :new.gen_date
        AND lno = v_lno;

        UPDATE leaveregd
        SET sl_up =0
        WHERE sl_up <> 0 AND  frm_date <= :new.gen_date AND to_date <= :new.gen_date
        AND lno = v_lno;

    end loop;
    close slc;


        /*** Update Loan Table if loan_bal = 0 ( means loan is cleared )**/

    open loanc;
    loop
    fetch loanc
        into v_loanid;

    exit when loanc%notfound;

        update loan set loan_balance = loan_balance - installment where loanid= v_loanid;

    end loop;
    close loanc;

    update loan set flag='Y' where loan_balance=0;


    ------------************UPDATE LOAN TABLE FOR ADJUSTIG LOAN***************---------
            update loan
            set flag = 'Y'
            where flag = 'N';
    ---------------------*****************************************---------------------

end;
/


CREATE OR REPLACE TRIGGER GL.sal_gen_trigger
after insert on sal_sheetm
for each row
declare
    -----------------------------
    CURSOR empc is select empid
            from emp
        where flag <> 'Y';   --NOT Fired/Retired/Left
    ------------------------------

    v_c            number(32);
    v_last_gen_date        date;
    v_join            date;
    v_slno            number(32);
    v_days            number(32);
    v_tot_sl        number(32,4);
    v_sl            number(32);
    v_tot_lwp        number(32,4);
    v_sl2            number(32);
    v_lwp_rem        varchar2(400);
    v_sl_rem        varchar2(400);
    v_empid            emp.empid%type;
    v_bsal            emp.basic_sal%type;
    v_oallow        emp.oth_allow%type;
    v_type            emp.staff_type%type;
    v_basic_ded        number(32,4);
    v_h_ded            number(32,4);
    v_med_ded          number(32,4);
    v_conv_ded         number(32,4);
    v_laun_ded         number(32,4);
    v_oth_ded_lwp          number(32,4);
    v_h_rent        number(32,4);
    v_med_allow        number(32,4);
    v_conv_allow        number(32,4);
    v_laun_allow        number(32,4);
    --v_oth_allow        number(32,4);
    v_pf            number(32,4);
    v_loan             number(32,4);
    v_oth_ded        number(32,4);
    v_tot_ded        number(32,4);
    v_gross_sal        number(32,4);
    v_gross_sal_ded        number(32,4);
    v_tot_sal        number(32,4);
    v_scale            emp.scale%type;
    v_dept            emp.deptid%type;
    v_lwpno            number(32);
    v_lno            number(32);
    v_fdate         date;
    v_tdate            date;
    v_lwp_up        number;
    v_sl_up            number;
    v_days_spent        number;
    v_lwp_days        number;
    v_stamp            number;
    v_lc             number;
    V_LWC             NUMBER;
    V_SLC            NUMBER;
    v_desigid        number;
    v_jd             number;
    v_jy             number;
    v_jm             number;
    v_jdy             number;
    v_old_allow        number(32,4);
    v_w_days_1        number(32);
    v_trdate        date;
    v_month            varchar2(100);
    v_year            varchar2(100);
    v_t_month        varchar2(100);
    v_t_year        varchar2(100);
    v_tc            number;
    v_w_days        number(32);
    v_old_basic        number(32,4);
    v_maxid            number;
    v_evt            varchar2(100);
    v_days_in_month    number(32);
    v_leave_date    date;

    -----------------------------
    CURSOR lwpc is select  Frm_date, to_date, nvl(days_spent,0), lwp_up
            from lwpregd
        WHERE lwpno = v_lwpno
        AND  (
            (flag is null AND frm_date >= :new.last_gen_date and to_date <= :new.gen_date)
            --OR (flag is null AND sanc_date >= :new.last_gen_date and to_date <= :new.gen_date)
            OR (lwp_up is not null and lwp_up <> 0 )
            );
    ------------------------------

    -----------------------------
    CURSOR slc is select  Frm_date, to_date, nvl(sl,0), sl_up
            from leaveregd
        WHERE lno = v_lno and sl is not null
        AND  (
            (flag is null AND  frm_date >= :new.last_gen_date and to_date <= :new.gen_date)
            --OR (flag is null AND  sanc_date >= :new.last_gen_date and to_date <= :new.gen_date)
            OR (sl_up is not null and sl_up <> 0)
            );
    ------------------------------

begin


    v_days_in_month := GETDAYS( :new.gen_date);


    open empc;
    loop
    fetch empc into v_empid;
    exit when empc%notfound;

    v_tc := 0;
    v_lwp_rem := ' ';
    v_sl_rem := ' ';
    v_basic_ded := 0;
    v_h_ded     := 0;


    --insert into tt values(v_empid);
    --dbms_output.put_line (v_empid);

        select basic_sal,nvl(oth_allow,0), staff_type,nvl(oth_ded,0), deptid,designationid,
            JOIN_DATE, nvl(LAUN_ALLOW,0),scale, leave_date
            into v_bsal,v_oallow, v_type, v_oth_ded, v_dept, v_desigid, v_join, v_laun_allow,v_scale, v_leave_date
            from emp where empid = v_empid;




        /*********88888888888 CHECK for TRANSFERRRRRR ********888888888********/

        select count(*) into v_tc from emp_event
            where EMPID = V_EMPID AND (event='transfer' OR event='promotion') AND cdate between
            to_date('01-'||:new.month||'-'||:new.year,'dd-month-yyyy') and :new.gen_date;

        if v_tc > 0  then

            --insert into tt values(v_empid);
            --insert into tt values(v_tc);
            select max(id) into v_maxid from emp_event
                where EMPID = V_EMPID AND (event='transfer' OR event='promotion') AND cdate between
                to_date('01-'||:new.month||'-'||:new.year,'dd-month-yyyy') and :new.gen_date;
                v_w_days := getdays(:new.gen_date);


            select nvl(old_alllow,0),nvl(old_basic,0),cdate,event into v_old_allow, v_old_basic, v_trdate,v_evt from emp_event
                where EMPID = V_EMPID AND id = v_maxid;

            --insert into tt values(v_evt);

            if v_old_allow>0 or v_old_basic>0 then
                select to_char(to_date(:new.gen_date,'dd-mm-yy'),'month') into v_month from dual;
                select to_char(to_date(:new.gen_date,'dd-mm-yy'),'yyyy') into v_year from dual;

                select to_char(to_date(v_trdate,'dd-mm-yy'),'month') into v_t_month from dual;
                select to_char(to_date(v_trdate,'dd-mm-yy'),'yyyy') into v_t_year from dual;

                if v_month = v_t_month AND  v_year = v_t_year then

                    if v_evt='promotion' then
                        v_sl_rem := 'Promotion on:'||to_char(v_trdate,'dd-mm-yy')||' New scale='||v_bsal;
                    elsif v_evt='transfer' then
                        v_sl_rem := 'Transfer on:'||to_char(v_trdate,'dd-mm-yy'); --||' New allowance='||v_oallow;
                    end if;

                    v_w_days_1 :=  to_number( to_char(to_date(v_trdate,'dd-mm-yy'),'dd') )-1  ;

                    v_old_allow := v_old_allow*v_w_days_1/v_w_days;
                    v_oallow := v_oallow*(v_w_days - v_w_days_1)/v_w_days + v_old_allow;

                    v_old_basic := v_old_basic*v_w_days_1/v_w_days;
                    --v_basic_ded := v_old_basic;
                    v_bsal := round(v_bsal*(v_w_days - v_w_days_1)/v_w_days + v_old_basic);

                end if;


            end if;

        end if;

        --_______________________________________________________________________


        ------***** GET the no of days in this month ****

        v_days         := 0;

        v_med_ded   := 0;
        v_conv_ded  := 0;
        v_laun_ded  := 0;
        v_oth_ded_lwp   := 0;


        v_tot_lwp :=0;
        v_tot_sl := 0;

        if v_scale <> 'cons' or v_scale is null then
            -- get house rent
            v_h_rent := v_bsal * 45/100;
            v_med_allow := 150;
            v_conv_allow := 150;
        end if;

--**** handle LEAVE dATE *********---


        if v_leave_date is not null then
            select to_char(to_date(:new.gen_date,'dd-mm-yy'),'month') into v_month from dual;
            select to_char(to_date(:new.gen_date,'dd-mm-yy'),'yyyy') into v_year from dual;

            select to_char(to_date(v_leave_date,'dd-mm-yy'),'month') into v_t_month from dual;
            select to_char(to_date(v_leave_date,'dd-mm-yy'),'yyyy') into v_t_year from dual;

            --dbms_output.put_line ('*********** '||v_l_month||' '|| v_l_year||' '||v_month||' '||v_year);
            /***************8  for EMP that LEFT *************/
            if v_month = v_t_month AND  v_year = v_t_year then

                v_w_days :=  to_number( to_char(to_date(v_leave_date,'dd-mm-yy'),'dd') ) -1 ;

                v_oallow := v_oallow*v_w_days/v_days_in_month;
                v_bsal := round(v_bsal*v_w_days/v_days_in_month);
                v_h_rent := v_h_rent*v_w_days/v_days_in_month;
                v_med_allow := v_med_allow*v_w_days/v_days_in_month;
                v_conv_allow := v_conv_allow*v_w_days/v_days_in_month;
                v_laun_allow := v_laun_allow*v_w_days/v_days_in_month;

                v_sl_rem := v_sl_rem||' Left on : '||to_char(v_leave_date,'dd-mm-yy');

            end if;
        end if;


        -- Handle joinging on current month NOT on 1st date of month

        v_month := null;
        v_year := null;
        v_t_month := null;
        v_t_year := null;

        v_w_days_1 := 0;

        if v_join is not null then

            --select
            v_month := to_char(to_date(v_join,'dd-mm-yy'),'month') ; --into v_month from dual;
            v_year  := to_char(to_date(v_join,'dd-mm-yy'),'yyyy'); -- into  from dual;

            v_t_month := to_char(to_date(to_date('01-'||:new.month||'-'||:new.year,'dd-month-yyyy'),'dd-mm-yy'),'month') ;
            v_t_year := to_char(to_date(to_date('01-'||:new.month||'-'||:new.year,'dd-month-yyyy'),'dd-mm-yy'),'yyyy') ;

            if v_month = v_t_month AND  v_year = v_t_year then
                v_w_days := getdays(:new.gen_date);
                v_w_days_1 :=  to_number( to_char(to_date(v_join,'dd-mm-yy'),'dd') )  ;

                if v_w_days_1 > 1 then

                    --v_lwp_rem := 'Joining : '||to_char(v_join,'dd-mm-yy');

                    v_basic_ded := v_basic_ded + v_bsal*(v_w_days_1-1)/v_w_days;
                    v_h_ded     := v_h_ded     + v_h_rent*(v_w_days_1-1)/v_w_days;
                    v_med_ded   := v_med_ded   + v_med_allow*(v_w_days_1-1)/v_w_days;
                    v_conv_ded  := v_conv_ded  + v_conv_allow*(v_w_days_1-1)/v_w_days;
                    v_laun_ded  := v_laun_ded  + v_laun_allow*(v_w_days_1-1)/v_w_days;
                    v_oth_ded_lwp   := v_oth_ded_lwp    + v_oallow*(v_w_days_1-1)/v_w_days;

                end if;
            end if;
        end if;


        --dbms_output.put_line (to_char(v_empid)||' lallow : '|| to_char(v_laun_allow));
        select count(lwpno) into v_lwc
            from LWPREGM where empid = v_empid;

        ------------------------------For LWP------------------------------------
        if v_lwc > 0 then
            select lwpno into v_lwpno
                from LWPREGM where empid = v_empid;
                ----------------------OUTPUTTTTTTTTTTTTTTTTTTT
            --dbms_output.put_line (to_char(v_empid)||' : '|| to_char(v_lwpno));
            -- **********************************get last sal gen date
                v_last_gen_date := :new.last_gen_date;

            -----*** GET LWP ******
            open lwpc;
            loop
            fetch lwpc
                into v_fdate, v_tdate, v_lwp_days, v_lwp_up;

            exit when lwpc%notfound;

            v_days_spent := v_lwp_days;
                    ----------------------OUTPUTTTTTTTTTTTTTTTTTTT
                --dbms_output.put_line ('Got LWP '||' for '||to_char(v_empid)||' : '|| to_char(v_fdate));
                if v_days_spent > 0 then --and (v_lwp_up is null OR v_lwp_up =0) then
                v_tot_lwp := v_tot_lwp + v_days_spent;

                    v_days := GETDAYS( v_fdate);
                    --dbms_output.put_line ('no of LWP '||' for '||to_char(v_empid)||' : '|| to_char(v_days_spent));

                    v_basic_ded := v_basic_ded + v_bsal/v_days*v_days_spent;
                    v_h_ded     := v_h_ded     + v_h_rent/v_days*v_days_spent;
                    v_med_ded   := v_med_ded   + v_med_allow/v_days*v_days_spent;
                    v_conv_ded  := v_conv_ded  + v_conv_allow/v_days*v_days_spent;
                    v_laun_ded  := v_laun_ded  + v_laun_allow/v_days*v_days_spent;
                    v_oth_ded_lwp   := v_oth_ded_lwp    + v_oallow/v_days*v_days_spent;

                    v_lwp_rem := v_lwp_rem||' '||to_char(v_fdate,'dd-mm-yy')||' to '||to_char(v_tdate,'dd-mm-yy')||'='||v_days_spent;
                end if;

                /***********************************************************/
                /**** Will be activated from the 2nd time ****/
                /*** this month there will be update for previous data ****/
                /**********************************************************/


                /*if  v_lwp_up >0 then
                    v_days := GETDAYS( v_fdate);
                    v_tot_lwp := v_tot_lwp + v_lwp_up;

                    v_basic_ded := v_basic_ded + v_bsal/v_days*v_lwp_up;
                    v_h_ded     := v_h_ded     + v_h_rent/v_days*v_lwp_up;
                    v_med_ded   := v_med_ded   + v_med_allow/v_days*v_lwp_up;
                    v_conv_ded  := v_conv_ded  + v_conv_allow/v_days*v_lwp_up;
                    v_laun_ded  := v_laun_ded  + v_laun_allow/v_days*v_lwp_up;
                    v_oth_ded_lwp   := v_oth_ded_lwp    + v_oallow/v_days*v_lwp_up;


        --*****adjustment****
        v_lwp_rem := v_lwp_rem||' Adjustment('||to_char(v_fdate,'dd-mm-yy')||' to '||to_char(v_tdate,'dd-mm-yy')||'='||abs(v_lwp_up)||')';
                end if;*/


            end loop;
            close lwpc;
        end if;

        -----*** GET SL ******

        if LOWER(v_type) = 'factory' or LOWER(v_type) = 'wages' THEN

            select count(LNO) into v_slc
                from LEAVEREGM where empid = v_empid;

            if v_slc > 0 then
                select lno into v_lno
                    from LEAVEREGM where empid = v_empid;
                    ----------------------OUTPUTTTTTTTTTTTTTTTTTTT


                open SLC;
                loop
                fetch SLC
                    into v_fdate, v_tdate, v_days_spent, v_sl_up;
                exit when slc%notfound;

                    if v_days_spent > 0 then --and (v_sl_up is null OR v_sl_up =0)then
                        v_days := GETDAYS( v_fdate);

                        V_DAYS_SPENT := V_DAYS_SPENT/2;
                        v_tot_sl := v_tot_sl + v_days_spent;
                        --dbms_output.put_line (to_char(v_empid)||' LNO days_spent : '|| to_char(V_DAYS_SPENT));

                        v_basic_ded := v_basic_ded + v_bsal/v_days*v_days_spent;
                        v_h_ded     := v_h_ded     + v_h_rent/v_days*v_days_spent;
                        v_med_ded   := v_med_ded   + v_med_allow/v_days*v_days_spent;
                        v_conv_ded  := v_conv_ded  + v_conv_allow/v_days*v_days_spent;
                        v_laun_ded  := v_laun_ded  + v_laun_allow/v_days*v_days_spent;
                        v_oth_ded_lwp   := v_oth_ded_lwp    + v_oallow/v_days*v_days_spent;

                        v_sl_rem := v_sl_rem||' '||to_char(v_fdate,'dd-mm-yy')||' to '||to_char(v_tdate,'dd-mm-yy')||'='||v_days_spent*2;
                    end if;
                /***********************************************************/
                /**** Will be activated from the 2nd time ****/
                /*** this month there will be update for previous data ****/
                /**********************************************************/
                    /*if v_sl_up > 0 then
                        v_days := GETDAYS( v_fdate);

                        v_sl_up := v_sl_up/2;
                        v_tot_sl := v_tot_sl + v_sl_up;

                        v_basic_ded := v_basic_ded + v_bsal/v_days*v_sl_up;
                        v_h_ded     := v_h_ded     + v_h_rent/v_days*v_sl_up;
                        v_med_ded   := v_med_ded   + v_med_allow/v_days*v_sl_up;
                        v_conv_ded  := v_conv_ded  + v_conv_allow/v_days*v_sl_up;
                        v_laun_ded  := v_laun_ded  + v_laun_allow/v_days*v_sl_up;
                        v_oth_ded_lwp   := v_oth_ded_lwp    + v_oallow/v_days*v_sl_up;



                    --******ADJUSTMENT*********
                    v_sl_rem := v_sl_rem||' Adjustment('||to_char(v_fdate,'dd-mm-yy')||' to '||to_char(v_tdate,'dd-mm-yy')||'='||abs(v_sl_up)||')';
                    end if;*/


                end loop;
                close slc;
            end if;
        END IF;





        --- GET LOAN Repayment Part -------------------------
        v_loan := 0;
        select count(*) into v_lc from loan
            where empid=v_empid and flag='N' and suspend<>'Y';
        if v_lc > 0 then

            select nvl( sum(installment),0)
                into v_loan
                from loan
                where empid=v_empid and flag='N' and suspend<>'Y';
        end if;

        --- get OTHER DED ----------
        select amt into v_stamp from stamp_price;


        /******** ROUND the calculations  ********/

        v_med_allow := round(v_med_allow);
        v_med_allow:= round(v_med_allow);
        v_laun_allow:= round(v_laun_allow);
        v_h_rent:= round(v_h_rent);
        v_conv_allow:= round(v_conv_allow);
        v_oallow:= round(v_oallow);
        v_basic_ded:= round(v_basic_ded);
        v_med_ded:= round(v_med_ded);
        v_h_ded:= round(v_h_ded);
        v_laun_ded:= round(v_laun_ded);
        v_conv_ded:= round(v_conv_ded);
        v_oth_ded_lwp:= round(v_oth_ded_lwp);

        --:= round();

        ---- GOSS_SALARY

        v_gross_sal    := nvl(v_bsal,0) + nvl(v_med_allow,0) + nvl(v_laun_allow,0) +
                        nvl(v_h_rent,0) + nvl(v_conv_allow,0) + nvl(v_oallow,0);
        v_gross_sal_ded    := nvl(v_basic_ded,0) + nvl(v_med_ded,0) +
                        nvl(v_h_ded,0) + nvl(v_laun_ded,0) +
                        nvl(v_conv_ded,0) + nvl(v_oth_ded_lwp,0);

        --- GET PF (self) ---------------------------------
        select pct_self into v_pf
            from pf_pct;

        v_jdy := to_number( to_char( v_join,'yyyy') );

        if v_join < '01-JAN-2000' then
            v_jdy := to_number( to_char( v_join,'yyyy') ) -100;
        end if;

        v_jy :=  to_number( to_char( :new.gen_date,'yyyy') )
                 - v_jdy ;


        v_jm :=  to_number( to_char( :new.gen_date,'mm') )
                 - to_number( to_char( v_join,'mm') ) ;

        v_jd := 12*v_jy + to_number( to_char( :new.gen_date,'mm') ) - to_number( to_char( v_join,'mm') );

        --dbms_output.put_line (to_char(v_empid)||' '|| v_jd);

        if v_jd > 6 then
            v_pf := (v_bsal-v_basic_ded)* (v_pf/100);
        else
            v_pf := 0;
            v_sl_rem := v_sl_rem||' Joining : '||to_char(v_join,'dd-mm-yy');

        end if;

--**************DEPRIVATION for Consolidated people******************

        if v_scale = 'cons' then
            v_pf := 0;
            v_h_rent := 0;
            v_med_allow := 0;
            v_conv_allow := 0;
            v_laun_allow := 0;

            v_h_ded := 0;
            v_med_ded := 0;
            v_conv_ded := 0;
            v_laun_ded := 0;

            v_gross_sal    :=     nvl(v_bsal,0) + nvl(v_med_allow,0) + nvl(v_laun_allow,0) +
                               nvl(v_h_rent,0) + nvl(v_conv_allow,0) + nvl(v_oallow,0);
            v_gross_sal_ded    := nvl(v_basic_ded,0) + nvl(v_med_ded,0) +
                            nvl(v_h_ded,0) + nvl(v_laun_ded,0) +
                            nvl(v_conv_ded,0) + nvl(v_oth_ded_lwp,0);

        end if;

        ---- TOT_DEDUCTION
        v_oth_ded := 0;  --------------------- Might need to get from emp table
        v_oth_ded := v_oth_ded + v_stamp;
        v_oth_ded:= round(v_oth_ded);
        v_pf:= round(v_pf);
        v_loan:= round(v_loan);

        v_tot_ded := nvl(v_pf,0) + nvl(v_loan,0) + nvl(v_oth_ded,0);

        v_tot_ded := round(v_tot_ded);

        ---- TOT_SALARY

        v_tot_sal := v_gross_sal - v_gross_sal_ded - v_tot_ded;

        v_tot_sal := round(v_tot_sal);


        --------****** INSERT into SAL_SHEETD *********-----------

        insert into SAL_SheetD (            salaryno,
                                slno,
                                empid,
                                deptid,
                                lwp,
                                lwp_date,
                                SL,
                                SL_date,
                                basic_sal,
                                basic_ded,
                                h_rent,
                                h_ded,
                                med_allow,
                                med_ded,
                                conv_allow,
                                conv_ded,
                                laun_allow,
                                laun_ded,
                                oth_allow,
                                oth_ded,
                                gross_sal,
                                gross_sal_ded,
                                pf,
                                advance,
                                other_deduction,
                                tot_ded,
                                tot_sal)
            values(:NEW.SALARYNO, sald_slno_sq.NEXTVAL, v_empid, v_dept, v_tot_lwp, v_lwp_rem, v_tot_sl, v_sl_rem,
                    v_bsal, v_basic_ded, v_h_rent,v_h_ded, v_med_allow,v_med_ded,
                    v_conv_allow, v_conv_ded, v_laun_allow, v_laun_ded, v_oallow, v_oth_ded_lwp,
                    v_gross_sal, v_gross_sal_ded, v_pf, v_loan,
                    v_oth_ded, v_tot_ded, v_tot_sal);


    end loop;  --<<----*****  END OF LOOP ******----
    close empc;
end;
/


CREATE OR REPLACE TRIGGER GL.stock_change
after update of closing_balance on stock
for each row
declare


begin

    update pm_journaldl
    set balance = balance - (:new.closing_balance - :old.closing_balance)
    where vdate = :new.closing_date+1
    and actname = 'Profit '||'&'||' Loss Account';

    update pm_journaldl
    set balance = balance + (:new.closing_balance - :old.closing_balance)
    where vdate = :new.closing_date+1
    and actcode = :new.actcode;

end;
/


CREATE OR REPLACE TRIGGER GL.tt
after insert on test
for each row
begin

    dbms_output.put_line('aaaaa');

end;
/


CREATE OR REPLACE TRIGGER GL.GL_VOUCHER_MAIN_AUDIT_TRG
      AFTER INSERT OR DELETE OR UPDATE ON GL.GL_VOUCHER_MAIN       FOR EACH ROW
BEGIN
     IF INSERTING THEN
        INSERT INTO GL_VOUCHER_MAIN_AUDIT
        (VC_NO, VC_DATE, VC_ENTERED, VJ_CODE, VC_ENTERED_BY, VC_POSTED_BY, VC_RECEIVED_BY, VC_PREPARED_BY, VC_CHECKED_BY, VC_APPROVED_BY, VC_POSTED_DATE, CUR_CODE, VC_CONV_RATE, VC_IS_POSTED, PAYEE_CODE, IS_CHEQUE, PM_CODE, VC_LETTER_REF_NO, IS_SYSTEM, PO_CLEA_DATE, VC_EDIT_BY, VC_EDIT_DATE, CHEQ_PAY_DATE, IS_MANUAL_PAY, EDIT_DEL_BY,EDIT_DEL_DATE, AUDIT_TYPE)
        values 
        (:NEW.VC_NO, :NEW.VC_DATE, :NEW.VC_ENTERED, :NEW.VJ_CODE, :NEW.VC_ENTERED_BY, :NEW.VC_POSTED_BY, :NEW.VC_RECEIVED_BY, :NEW.VC_PREPARED_BY, 
        :NEW.VC_CHECKED_BY, :NEW.VC_APPROVED_BY, :NEW.VC_POSTED_DATE, :NEW.CUR_CODE, :NEW.VC_CONV_RATE, :NEW.VC_IS_POSTED,
         :NEW.PAYEE_CODE, :NEW.IS_CHEQUE, :NEW.PM_CODE, :NEW.VC_LETTER_REF_NO, :NEW.IS_SYSTEM, :NEW.PO_CLEA_DATE, :NEW.VC_EDIT_BY, :NEW.VC_EDIT_DATE, 
         :NEW.CHEQ_PAY_DATE, :NEW.IS_MANUAL_PAY, :NEW.VC_ENTERED_BY, SYSDATE,'I');
     ELSIF UPDATING THEN
        INSERT INTO GL_VOUCHER_MAIN_AUDIT
        (VC_NO, VC_DATE, VC_ENTERED, VJ_CODE, VC_ENTERED_BY, VC_POSTED_BY, VC_RECEIVED_BY, VC_PREPARED_BY, VC_CHECKED_BY, VC_APPROVED_BY, VC_POSTED_DATE, CUR_CODE, VC_CONV_RATE, VC_IS_POSTED, PAYEE_CODE, IS_CHEQUE, PM_CODE, VC_LETTER_REF_NO, IS_SYSTEM, PO_CLEA_DATE, VC_EDIT_BY, VC_EDIT_DATE, CHEQ_PAY_DATE, IS_MANUAL_PAY, EDIT_DEL_BY, EDIT_DEL_DATE, AUDIT_TYPE)
        values 
        (:NEW.VC_NO, :NEW.VC_DATE, :NEW.VC_ENTERED, :NEW.VJ_CODE, :NEW.VC_ENTERED_BY, :NEW.VC_POSTED_BY, :NEW.VC_RECEIVED_BY, :NEW.VC_PREPARED_BY, 
        :NEW.VC_CHECKED_BY, :NEW.VC_APPROVED_BY, :NEW.VC_POSTED_DATE, :NEW.CUR_CODE, :NEW.VC_CONV_RATE, :NEW.VC_IS_POSTED,
         :NEW.PAYEE_CODE, :NEW.IS_CHEQUE, :NEW.PM_CODE, :NEW.VC_LETTER_REF_NO, :NEW.IS_SYSTEM, :NEW.PO_CLEA_DATE, :NEW.VC_EDIT_BY, 
         :NEW.VC_EDIT_DATE, :NEW.CHEQ_PAY_DATE, :NEW.IS_MANUAL_PAY, :NEW.VC_EDIT_BY, SYSDATE,'U');
     ELSE
        INSERT INTO GL_VOUCHER_MAIN_AUDIT
        (VC_NO, VC_DATE, VC_ENTERED, VJ_CODE, VC_ENTERED_BY, VC_POSTED_BY, VC_RECEIVED_BY, VC_PREPARED_BY, VC_CHECKED_BY, VC_APPROVED_BY, VC_POSTED_DATE, CUR_CODE, VC_CONV_RATE, VC_IS_POSTED, PAYEE_CODE, IS_CHEQUE, PM_CODE, VC_LETTER_REF_NO, IS_SYSTEM, PO_CLEA_DATE, VC_EDIT_BY, VC_EDIT_DATE, CHEQ_PAY_DATE, IS_MANUAL_PAY, EDIT_DEL_BY, EDIT_DEL_DATE, AUDIT_TYPE)
        values 
        (:OLD.VC_NO, :OLD.VC_DATE, :OLD.VC_ENTERED, :OLD.VJ_CODE, :OLD.VC_ENTERED_BY, :OLD.VC_POSTED_BY, :OLD.VC_RECEIVED_BY, :OLD.VC_PREPARED_BY, 
        :OLD.VC_CHECKED_BY, :OLD.VC_APPROVED_BY, :OLD.VC_POSTED_DATE, :OLD.CUR_CODE, :OLD.VC_CONV_RATE, :OLD.VC_IS_POSTED,
         :OLD.PAYEE_CODE, :OLD.IS_CHEQUE, :OLD.PM_CODE, :OLD.VC_LETTER_REF_NO, :OLD.IS_SYSTEM, :OLD.PO_CLEA_DATE, :OLD.VC_EDIT_BY, :OLD.VC_EDIT_DATE, 
         :OLD.CHEQ_PAY_DATE, :OLD.IS_MANUAL_PAY, :OLD.VC_EDIT_BY, SYSDATE,'D');
     END IF;
    END;
/


CREATE OR REPLACE TRIGGER GL.ot_distribute
after update of distributed on over_timem
for each row
Declare

    --v_fdate        date;
    v_days        number(32);
    v_c        number(32);
    v_empid        number(32);
    v_desigid        number(32);
    v_tot        number(32,4);
    --v_basic        number(32,4);
    V_TOTBD        number(34,6);
    v_1        number(34,6);
    v_2        number(34,6);
    v_3        number(34,6);
    v_4        number(34,6);
    v_5        number(34,6);
    v_6        number(34,6);
    v_7        number(34,6);
    v_8        number(34,6);
    v_9        number(34,6);
    v_10        number(34,6);
    v_11        number(34,6);
    v_rest        number(34,6);
    v_totrest    number(34,6);
    v_rate        number(32,4);
    v_basic     number(32,4);

    ---------------------------------------------------------------------------------------------------
    ------------------------------CURSOR 4 Over Time---------------------------------------------------
    ---------------------------------------------------------------------------------------------------
    CURSOR ot is select empid,  desigid, nvl(total,0)
                    from over_timed
                    where otno =:new.otno;
    ---------------------------------------------------------------------------------------------------



begin

    dbms_output.put_line('1 ');

    if :new.distributed = 'Y' AND  :old.distributed is null then

    dbms_output.put_line('2 ');

        open ot;
        loop
        fetch ot into v_empid,v_desigid, v_tot;
        exit when ot%notfound;

            /*************** DO it for BDGGGGGGGGGGGGGG **************/


            if v_tot > 0 then

                select count(*) into v_c from otbdgm where month=:new.month
                                AND year= :new.year ;
                if v_c = 0 then
                    insert into otbdgm (otno, month, year, F1)
                        values (:new.otno, :new.month, :new.year,  'N');
                end if;

                dbms_output.put_line('3 '||v_empid);


                select basic_sal into v_basic from emp where empid= v_empid;

                v_rate := 2*(v_basic/208.0);


                /************ DO OT_DBG ************************************/

                v_rest := v_tot;

                v_1 := null;
                v_2 :=null;
                v_3 := null;
                v_4 :=null;
                v_5 := null;
                v_6 :=null;
                v_7 := null;
                v_8 :=null;
                v_9 := null;
                v_10 :=null;
                v_11 := null;



                if v_rest >= 4 then
                    v_1 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_1 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_2
                if v_rest >= 4 then
                    v_2 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_2 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_4
                if v_rest >= 4 then
                    v_3 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_3 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_4
                if v_rest >= 4 then
                    v_4 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_4 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_5
                if v_rest >= 4 then
                    v_5 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_5 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_6
                if v_rest >= 4 then
                    v_6 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_6 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_7
                if v_rest >= 4 then
                    v_7 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_7 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_8
                if v_rest >= 4 then
                    v_8 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_8 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_9
                if v_rest >= 4 then
                    v_9 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_9 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_10
                if v_rest >= 4 then
                    v_10 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_10 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_11
                if v_rest >= 4 then
                    v_11 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_11 := v_rest;
                    v_rest :=0;
                end if;


                v_totbd := nvl(v_1,0)+nvl(v_2,0)+nvl(v_3,0)+nvl(v_4,0)+nvl(v_5,0)+nvl(v_6,0)+
                        nvl(v_7,0)+nvl(v_8,0)+nvl(v_9,0)+nvl(v_10,0)+nvl(v_11,0);

                insert into otbdgd ( OTNO,EMPID,DESIGID,ONE,TWO,THREE,FOUR,FIVE,
                        SIX,SEVEN,EIGHT,NINE,TEN,ELEVEN,TOTAL,RATE,AMOUNT)
                    values (:new.otno,v_empid,v_desigid,v_1,v_2,v_3,v_4,v_5,
                        v_6,v_7,v_8,v_9,v_10,v_11,v_totbd,round(v_rate),round(v_rate*v_totbd));

                dbms_output.put_line('----------4');

            end if;


            /*************** DO it for RESTTTTTTTTTTTTTTTTTTTTTTt   **************/

            if v_rest > 0 then

                select count(*) into v_c from otrestm where month=:new.month
                                AND year= :new.year ;
                if v_c = 0 then
                    insert into otrestm (otno, month, year, F1)
                        values (:new.otno, :new.month, :new.year, 'N');
                end if;

                --dbms_output.put_line('----------1');

                /************ DO OT_REST ************************************/



                v_1 := null;
                v_2 :=null;
                v_3 := null;
                v_4 :=null;
                v_5 := null;
                v_6 :=null;
                v_7 := null;
                v_8 :=null;
                v_9 := null;
                v_10 :=null;
                v_11 := null;


                if v_rest >= 4 then
                    v_1 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_1 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_2
                if v_rest >= 4 then
                    v_2 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_2 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_3
                if v_rest >= 4 then
                    v_3 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_3 := v_rest;
                    v_rest :=0;
                end if;

                ----------------------------v_4
                if v_rest >= 4 then
                    v_4 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_4 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_5
                if v_rest >= 4 then
                    v_5 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_5 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_6
                if v_rest >= 4 then
                    v_6 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_6 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_7
                if v_rest >= 4 then
                    v_7 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_7 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_8
                if v_rest >= 4 then
                    v_8 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_8 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_9
                if v_rest >= 4 then
                    v_9 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_9 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_10
                if v_rest >= 4 then
                    v_10 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_10 := v_rest;
                    v_rest :=0;
                end if;
                ----------------------------v_11
                if v_rest >= 4 then
                    v_11 := 4;
                    v_rest := v_rest -4 ;
                elsif v_rest > 0 then
                    v_11 := v_rest;
                    v_rest :=0;
                end if;


                v_totrest := nvl(v_1,0)+nvl(v_2,0)+nvl(v_3,0)+nvl(v_4,0)+nvl(v_5,0)+nvl(v_6,0)+
                        nvl(v_7,0)+nvl(v_8,0)+nvl(v_9,0)+nvl(v_10,0)+nvl(v_11,0);



                insert into otrestd ( OTNO,EMPID,DESIGID,ONE,TWO,THREE,FOUR,FIVE,
                        SIX,SEVEN,EIGHT,NINE,TEN,ELEVEN,TOTAL,RATE,AMOUNT)
                    values (:new.otno,v_empid,v_desigid,v_1,v_2,v_3,v_4,v_5,
                        v_6,v_7,v_8,v_9,v_10,v_11,v_totrest,round(v_rate),round(v_rate*v_totrest));


                dbms_output.put_line('----------4');
            end if;

        end loop;
        close ot;
    end if;

end;
/


