CREATE OR REPLACE TRIGGER GL.GL_VOUCHER_DETAIL_AUDIT_TRG
      AFTER INSERT OR DELETE OR UPDATE ON GL.GL_VOUCHER_DETAIL       FOR EACH ROW
BEGIN
     IF INSERTING THEN
        INSERT INTO GL_VOUCHER_DETAIL_AUDIT
        values 
        (:NEW.VC_NO, :NEW.COA_CODE, :NEW.RC_CODE, :NEW.VD_DESCRIPTION, :NEW.VD_REFERENCE, :NEW.VD_UNPOSTED_DR_AMT, :NEW.VD_UNPOSTED_CR_AMT, 
        :NEW.VD_ENTERED_DR_AMT, :NEW.VD_ENTERED_CR_AMT, :NEW.VD_POSTED_DR_AMT, :NEW.VD_POSTED_CR_AMT, :NEW.COA_SOURCE, :NEW.SUP_CODE, :NEW.SLNO, :NEW.BCODE,'I');
     ELSIF UPDATING THEN
        INSERT INTO GL_VOUCHER_DETAIL_AUDIT
        values 
        (:NEW.VC_NO, :NEW.COA_CODE, :NEW.RC_CODE, :NEW.VD_DESCRIPTION, :NEW.VD_REFERENCE, :NEW.VD_UNPOSTED_DR_AMT, :NEW.VD_UNPOSTED_CR_AMT, 
        :NEW.VD_ENTERED_DR_AMT, :NEW.VD_ENTERED_CR_AMT, :NEW.VD_POSTED_DR_AMT, :NEW.VD_POSTED_CR_AMT, :NEW.COA_SOURCE, :NEW.SUP_CODE, :NEW.SLNO, :NEW.BCODE,'U');
     ELSE
        INSERT INTO GL_VOUCHER_DETAIL_AUDIT
        values
       (:OLD.VC_NO, :OLD.COA_CODE, :OLD.RC_CODE, :OLD.VD_DESCRIPTION, :OLD.VD_REFERENCE, :OLD.VD_UNPOSTED_DR_AMT, :OLD.VD_UNPOSTED_CR_AMT, 
        :OLD.VD_ENTERED_DR_AMT, :OLD.VD_ENTERED_CR_AMT, :OLD.VD_POSTED_DR_AMT, :OLD.VD_POSTED_CR_AMT, :OLD.COA_SOURCE, :OLD.SUP_CODE, :OLD.SLNO, :OLD.BCODE,'D');
     END IF;
    END;
/


